import './app-craps-table.js';
import { prepareDecimatorReplay } from '../craps/decimator-replay.js';
import { decimatorTableOptions } from '../craps/decimator-table.js';

/** Load Decimator data into the existing craps resolver, with its own scoring skin. */
export function mountDecimatorBattle(snapshot, { names = new Map(), onResults = () => {}, onClose = () => {},
  onRetry, prepareReplay = prepareDecimatorReplay, ...controls } = {}) {
  if (!document.querySelector('link[data-decimator-craps]')) {
    const link = document.createElement('link'); link.rel = 'stylesheet';
    link.href = '/app/styles/craps-table.css?v=decimator-skin-20261006';
    link.dataset.decimatorCraps = ''; document.head.append(link);
  }
  const element = document.createElement('div'); element.className = 'decimator-craps-host';
  const status = document.createElement('section'); status.className = 'decimator-battle-status';
  status.setAttribute('role', 'status');
  const logo = document.createElement('img'); logo.src = '/app/assets/decimator-logo.svg'; logo.alt = 'Decimator';
  const title = document.createElement('strong'); title.textContent = 'PREPARING YOUR REPLAY';
  const detail = document.createElement('p'); detail.textContent = 'Verifying the battle against its recorded results…';
  status.append(logo, title, detail);
  const table = document.createElement('app-craps-table');
  element.append(status, table);
  const abort = new AbortController(); let disposed = false;
  (snapshot.preparedReplay ? Promise.resolve(snapshot.preparedReplay)
    : snapshot.preparedReplayError ? Promise.reject(new Error(snapshot.preparedReplayError))
    : prepareReplay(snapshot, { signal: abort.signal })).then(replay => {
    if (disposed) return;
    table.open(decimatorTableOptions(snapshot, replay, { names, ...controls,
      onResolutionAcknowledged: onResults, onClose,
    }));
    status.hidden = true;
  }).catch(error => {
    if (disposed) return;
    status.hidden = false;
    status.dataset.state = 'error';
    title.textContent = 'REPLAY UNAVAILABLE';
    detail.textContent = 'The replay could not be verified. You can try again or view the recorded results.';
    const actions = document.createElement('div'); actions.className = 'decimator-battle-status__actions';
    if (onRetry) {
      const retry = document.createElement('button'); retry.type = 'button'; retry.textContent = 'RETRY REPLAY';
      retry.onclick = onRetry; actions.append(retry);
    }
    const results = document.createElement('button'); results.type = 'button'; results.textContent = 'VIEW RECORDED RESULTS';
    results.onclick = () => onResults({ fallback: true }); actions.append(results); status.append(actions);
  });
  return { element, table, destroy() { disposed = true; abort.abort(); table.remove(); } };
}
